{
  "decision-sequence-field-heat-removal": "WITH schedules AS (SELECT a.ticket_id AS first_ticket, b.ticket_id AS second_ticket, c.ticket_id AS third_ticket, a.run_hours AS f1, a.run_hours + b.run_hours AS f2, a.run_hours + b.run_hours + c.run_hours AS f3, a.due_hour AS d1, b.due_hour AS d2, c.due_hour AS d3, a.hourly_cents AS r1, b.hourly_cents AS r2, c.hourly_cents AS r3 FROM tunnel_ticket AS a JOIN tunnel_ticket AS b ON b.ticket_id <> a.ticket_id JOIN tunnel_ticket AS c ON c.ticket_id NOT IN (a.ticket_id, b.ticket_id)) SELECT first_ticket, second_ticket, third_ticket, f1*r1 + f2*r2 + f3*r3 AS exposure_cents FROM schedules WHERE f1 <= d1 AND f2 <= d2 AND f3 <= d3 ORDER BY exposure_cents, first_ticket COLLATE BINARY, second_ticket COLLATE BINARY, third_ticket COLLATE BINARY LIMIT 1",
  "decision-sequence-leak-repairs-before-refill": "WITH pairs AS (SELECT a.site_code AS first_site, b.site_code AS second_site, a.repair_min AS first_finish, a.repair_min + t.drive_min + b.repair_min AS finish_min, a.litres_per_min AS first_rate, b.litres_per_min AS second_rate FROM crew_trip AS t JOIN leak_site AS a ON a.site_code = t.origin_code JOIN leak_site AS b ON b.site_code = t.dest_code WHERE a.site_code <> b.site_code) SELECT first_site, second_site, finish_min, (60 - first_finish)*first_rate + (60 - finish_min)*second_rate AS saved_litres FROM pairs WHERE finish_min <= 60 ORDER BY saved_litres DESC, finish_min, first_site COLLATE BINARY, second_site COLLATE BINARY LIMIT 1",
  "decision-sequence-single-dock-refills": "WITH orders AS (SELECT a.ticket_id AS first_ticket, b.ticket_id AS second_ticket, c.ticket_id AS third_ticket, a.trailer_id AS id1, b.trailer_id AS id2, c.trailer_id AS id3, max(0, a.ready_min) + a.work_min AS f1, b.ready_min AS ready2, b.work_min AS work2, c.ready_min AS ready3, c.work_min AS work3, a.due_min AS d1, b.due_min AS d2, c.due_min AS d3, a.late_rate AS r1, b.late_rate AS r2, c.late_rate AS r3 FROM dispatch_ticket AS a JOIN dispatch_ticket AS b ON b.ticket_id <> a.ticket_id JOIN dispatch_ticket AS c ON c.ticket_id NOT IN (a.ticket_id, b.ticket_id)), second_done AS (SELECT *, max(f1, ready2) + work2 AS f2 FROM orders), third_done AS (SELECT *, max(f2, ready3) + work3 AS f3 FROM second_done) SELECT first_ticket, second_ticket, third_ticket, max(0, f1-d1)*r1 + max(0, f2-d2)*r2 + max(0, f3-d3)*r3 AS penalty_points FROM third_done ORDER BY penalty_points, id1 COLLATE BINARY, id2 COLLATE BINARY, id3 COLLATE BINARY LIMIT 1",
  "decision-sequence-three-cutter-jobs-before-dispatch": "WITH orders AS (SELECT s.card_id, a.job_id AS first_job, b.job_id AS second_job, c.job_id AS third_job, a.cut_minutes + (s.initial_pos <> a.fence_pos)*s.change_minutes AS f1, b.cut_minutes + (a.fence_pos <> b.fence_pos)*s.change_minutes AS elapsed2, c.cut_minutes + (b.fence_pos <> c.fence_pos)*s.change_minutes AS elapsed3, a.due_minute AS d1, b.due_minute AS d2, c.due_minute AS d3, a.late_rate AS r1, b.late_rate AS r2, c.late_rate AS r3 FROM setup_card AS s CROSS JOIN cutter_job AS a JOIN cutter_job AS b ON b.job_id <> a.job_id JOIN cutter_job AS c ON c.job_id NOT IN (a.job_id, b.job_id)), finishes AS (SELECT *, f1 + elapsed2 AS f2, f1 + elapsed2 + elapsed3 AS finish_minute FROM orders) SELECT card_id, first_job, second_job, third_job, max(0, f1-d1)*r1 + max(0, f2-d2)*r2 + max(0, finish_minute-d3)*r3 AS penalty_cents, finish_minute FROM finishes ORDER BY penalty_cents, finish_minute, first_job COLLATE BINARY, second_job COLLATE BINARY, third_job COLLATE BINARY LIMIT 1"
}
